import{_ as o,o as l,c as a,a2 as i}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"常见问题与排查","description":"","frontmatter":{"title":"常见问题与排查","order":25},"headers":[],"relativePath":"zh/learn/mod/troubleshooting.md","filePath":"zh/learn/mod/troubleshooting.md","lastUpdated":1786943111000}'),t={name:"zh/learn/mod/troubleshooting.md"};function r(n,e,d,c,s,h){return l(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="常见问题与排查" tabindex="-1">常见问题与排查 <a class="header-anchor" href="#常见问题与排查" aria-label="Permalink to &quot;常见问题与排查&quot;">​</a></h1><h2 id="加载失败" tabindex="-1">加载失败 <a class="header-anchor" href="#加载失败" aria-label="Permalink to &quot;加载失败&quot;">​</a></h2><p><strong>症状</strong>：UMM 列表里看不到你的 Mod，或显示加载失败。</p><p><strong>排查</strong>：</p><ol><li><code>Info.json</code> 的 <code>AssemblyName</code> 是否等于实际 DLL 文件名</li><li><code>EntryMethod</code> 是否为 <code>命名空间.类.Load</code></li><li>DLL 是否真的复制到了 <code>Mods/MyFirstMod/</code> 目录</li><li><code>Load</code> 是否返回 <code>true</code></li><li>查看 UMM 日志中的错误信息</li></ol><h2 id="补丁不生效" tabindex="-1">补丁不生效 <a class="header-anchor" href="#补丁不生效" aria-label="Permalink to &quot;补丁不生效&quot;">​</a></h2><p><strong>症状</strong>：写好了 Harmony 补丁，但游戏行为没变化。</p><p><strong>排查</strong>（详见 <a href="./harmony-lifecycle">补丁生命周期</a>）：</p><ol><li>类必须是 <code>public static class</code> 且带 <code>[HarmonyPatch]</code></li><li><code>PatchAll</code> 是否在 <code>OnToggle(true)</code> 中被调用</li><li>目标方法名 / 类名 / 参数类型是否完全匹配（注意重载）</li><li>用 <code>GetPatchInfo</code> 检查补丁是否真的应用了</li><li>是否在 Mod 启用前目标方法已经被调用过</li></ol><h2 id="nullreferenceexception" tabindex="-1">NullReferenceException <a class="header-anchor" href="#nullreferenceexception" aria-label="Permalink to &quot;NullReferenceException&quot;">​</a></h2><p><strong>症状</strong>：日志中出现 <code>NullReferenceException</code>。</p><p><strong>排查</strong>：</p><ol><li>是否在 <code>OnToggle</code> 之前就访问了 <code>Settings</code></li><li><code>__instance</code> 是否可能为 null（静态方法或空引用）</li><li>反编译确认目标方法实际的字段 / 属性名</li></ol><h2 id="transpiler-崩溃或行为异常" tabindex="-1">Transpiler 崩溃或行为异常 <a class="header-anchor" href="#transpiler-崩溃或行为异常" aria-label="Permalink to &quot;Transpiler 崩溃或行为异常&quot;">​</a></h2><p><strong>症状</strong>：应用 Transpiler 后游戏崩溃，或行为变得诡异。</p><p><strong>排查</strong>（详见 <a href="./harmony-transpiler-practice">Transpiler 实战</a>）：</p><ol><li>用 dnSpy 查看目标方法的真实 IL，确认匹配的指令序列存在</li><li>匹配失败时降级处理（<code>IsValid</code> 检查），不要直接抛异常</li><li>先加日志输出指令序列，逐个核对</li></ol><h2 id="设置没保存" tabindex="-1">设置没保存 <a class="header-anchor" href="#设置没保存" aria-label="Permalink to &quot;设置没保存&quot;">​</a></h2><p><strong>症状</strong>：重启游戏后设置恢复默认。</p><p><strong>排查</strong>：</p><ol><li><code>OnSaveGUI</code> 是否绑定到 <code>Settings.OnSaveGUI</code></li><li><code>Settings.Save</code> 是否被调用</li><li>属性类型是否为 UMM 支持的类型</li></ol><h2 id="ci-构建失败" tabindex="-1">CI 构建失败 <a class="header-anchor" href="#ci-构建失败" aria-label="Permalink to &quot;CI 构建失败&quot;">​</a></h2><p><strong>症状</strong>：GitHub Actions 报错找不到 DLL。</p><p><strong>排查</strong>（详见 <a href="./github-actions">GitHub Actions 自动构建</a>）：</p><ol><li>私有 lib 仓库目录结构是否与 <code>HintPath</code> 一致</li><li><code>LIBS_PAT</code> Secret 是否创建、拼写是否一致</li><li>PAT 是否有 <code>Contents: Read</code> 权限</li><li>本地路径的 <code>Condition</code> 是否会在 CI 中被覆盖</li></ol><h2 id="游戏闪退" tabindex="-1">游戏闪退 <a class="header-anchor" href="#游戏闪退" aria-label="Permalink to &quot;游戏闪退&quot;">​</a></h2><p><strong>症状</strong>：启用 Mod 后游戏直接崩溃。</p><p><strong>排查</strong>：</p><ol><li>查看 <code>Player.log</code> 最后的异常堆栈</li><li>禁用所有 Mod 逐个启用，二分定位</li><li>如果指向你的补丁，用 <code>Finalizer</code> 捕获异常避免直接崩溃</li><li>确认没有把游戏二进制带进构建产物（这会造成加载冲突）</li></ol><h2 id="你学到了什么" tabindex="-1">你学到了什么 <a class="header-anchor" href="#你学到了什么" aria-label="Permalink to &quot;你学到了什么&quot;">​</a></h2><ul><li>常见问题的一线排查思路</li><li>每个问题对应的详细章节位置</li></ul><h2 id="系列完结-🎉" tabindex="-1">系列完结 🎉 <a class="header-anchor" href="#系列完结-🎉" aria-label="Permalink to &quot;系列完结 🎉&quot;">​</a></h2><p>你已经走完了 ADOFAI Mod 开发的完整流程。接下来可以：</p><ul><li>探索<a href="./../../libs/">库文档</a>，用代码处理关卡文件</li><li>体验<a href="./../../mods/online-tools/">在线工具</a>，或为<a href="./../../mods/">使用指南</a>补充你的 Mod 教程</li></ul>',34)])])}const g=o(t,[["render",r]]);export{u as __pageData,g as default};
